    ('90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Quiz — Conservation et non-conservation', 'Physique-Chimie', '1re', 'L’énergie mécanique : énergies cinétique et potentielle', '7d854675-b00e-51c5-b5fc-2d08b837e722'::uuid),
    ('89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Quiz — Puissance, effet Joule et rendement', 'Physique-Chimie', '1re', 'L’énergie électrique', '0b66d006-f8a9-5599-8dfd-867d81355aa0'::uuid),
    ('898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Quiz — Compter les entités sans les compter', 'Physique-Chimie', '1re', 'La mole et ses formules', 'aaa7a5eb-183d-5d93-b0ca-4dac1b711b37'::uuid),
    ('8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'Quiz — Doser une espèce colorée sans la toucher', 'Physique-Chimie', '1re', 'Absorbance et spectre d’absorption', '0f3d9a08-7f8a-572b-b730-971831c7a036'::uuid),
    ('1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Quiz — Avancement, tableau et réactif limitant', 'Physique-Chimie', '1re', 'Modélisation de l’évolution d’une réaction chimique', '9492373c-2477-51c4-8e6c-fb93748ac61b'::uuid),
    ('e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Quiz — Trouver une concentration par une réaction', 'Physique-Chimie', '1re', 'Dosage par titrage', 'fa718b0b-3376-5f0b-95e6-738d4fe5bc9d'::uuid),
    ('307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Quiz — Compter les électrons de valence', 'Physique-Chimie', '1re', 'Représentation de Lewis d’un atome et d’une molécule', '1f82a9a8-e99e-5f27-9217-58277e1b900d'::uuid),
    ('a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Quiz — Quand une liaison n’est pas partagée à égalité', 'Physique-Chimie', '1re', 'Électronégativité des atomes et polarité des molécules', 'e2bb0d08-0a29-5253-955f-204b9d5fd762'::uuid),
    ('9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Quiz — Ce qui tient les entités ensemble', 'Physique-Chimie', '1re', 'Cohésion de la matière', 'e11750fb-a34f-5861-9aa5-5d764757045e'::uuid),
    ('a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Quiz — Faire passer une espèce d’une phase à l’autre', 'Physique-Chimie', '1re', 'Solubilité et extraction par solvant', 'a59d796f-3116-53c9-afba-2557014fdfa0'::uuid),
    ('be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Quiz — Écrire et nommer une molécule organique', 'Physique-Chimie', '1re', 'Les différentes représentations des molécules et leur nomenclature', '8d31a101-58b0-5c9e-a133-44827f191d21'::uuid),
    ('fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Quiz — Fabriquer, isoler, purifier, identifier', 'Physique-Chimie', '1re', 'Synthèse organique', 'fb70808e-ad27-5001-b74b-57ecdc1d87bb'::uuid),
    ('87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Quiz — Énergie libérée et bilan de matière', 'Physique-Chimie', '1re', 'Les réactions de combustion', '39d47533-e93a-5433-b917-0651a414af46'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('bfb3b7c0-83a7-51cb-b566-789bd6b01e80'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Quelle est l’unité de pression du Système international ?', 'mcq', '["Le pascal","Le newton","Le bar","Le joule"]'::jsonb, 0, '1 Pa = 1 N/m² ; le bar et l’hectopascal en sont des multiples pratiques.', 1),
    ('31d477a8-5c56-52db-ab07-c1df442f992e'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Dans un liquide au repos, deux points à la même profondeur sont à la même pression.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le fondement du principe des vases communicants.', 2),
    ('aee10927-1673-5b89-af1f-e654aeacebeb'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'À quoi est égale la poussée d’Archimède ?', 'mcq', '["Au poids du fluide déplacé","Au poids du corps immergé","À la pression atmosphérique","Au volume du corps immergé"]'::jsonb, 0, 'Elle est verticale et dirigée vers le haut.', 3),
    ('064cd5f9-ea2d-5549-8a3d-028e905ba52e'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Que dit la loi de Mariotte ?', 'mcq', '["Le produit p × V d’un gaz est constant à température constante","La pression augmente avec la profondeur","La pression est proportionnelle à la température","Le volume d’un liquide est constant"]'::jsonb, 0, 'Elle ne s’applique qu’aux gaz, à température fixée.', 4),
    ('f1622e03-6896-514d-9d3f-4191238c84e9'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Une force pressante s’exerce parallèlement à la surface.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est toujours PERPENDICULAIRE à la surface pressée.', 5),
    ('195526f3-8f14-5128-8e3c-27d60ea49d4d'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Que devient la pression si l’on double la surface, à force pressante constante ?', 'mcq', '["Elle est divisée par deux","Elle est doublée","Elle est inchangée","Elle est multipliée par quatre"]'::jsonb, 0, 'p = F / S : la pression est inversement proportionnelle à la surface.', 6),
    ('6e53d213-529c-563a-9c8d-a26a04d3adca'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'Un corps flotte si sa masse volumique moyenne est inférieure à celle du fluide.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La poussée d’Archimède compense alors le poids avant immersion totale.', 7),
    ('d0e0a1b6-3cbe-5ed5-bef0-681a6312b7e6'::uuid, '27693583-f72f-5c50-b385-dcb4a003b027'::uuid, 'De quoi dépend l’augmentation de pression dans un liquide au repos ?', 'mcq', '["De la masse volumique du liquide et de la profondeur","De la forme du récipient","De la surface libre du liquide","Du volume total de liquide"]'::jsonb, 0, 'p augmente de ρ × g × h, indépendamment de la forme du récipient.', 8),
    ('2b7fb059-00e6-5b45-b877-c85d4445dc84'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Que faut-il choisir avant de décrire un mouvement ?', 'mcq', '["Un référentiel","Une force","Une masse","Une énergie"]'::jsonb, 0, 'Un mouvement n’a de sens que relativement à un référentiel.', 1),
    ('3ae4369c-e403-52e5-8140-20fc5e23cb4c'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Un mobile en mouvement circulaire uniforme a une accélération nulle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La direction du vecteur vitesse change : l’accélération est dirigée vers le centre.', 2),
    ('93558658-9ecb-5886-b805-bccd000821fb'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Que dit la deuxième loi de Newton ?', 'mcq', '["La somme des forces est égale au produit de la masse par l’accélération","Toute action entraîne une réaction opposée","Un corps isolé garde une vitesse constante","L’énergie se conserve"]'::jsonb, 0, 'Σ F = m × a, dans un référentiel galiléen.', 3),
    ('6e54a1a3-5c85-5f51-8b97-47f1da4af3cf'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Les deux forces de la troisième loi de Newton se compensent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles s’appliquent à DEUX corps différents : elles ne peuvent pas se compenser.', 4),
    ('9f0cc1cb-bd18-5084-ac9f-93165dd1ff06'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'En chute libre, de quoi dépend l’accélération d’un corps ?', 'mcq', '["Uniquement de l’intensité de pesanteur","De sa masse","De sa forme","De sa vitesse initiale"]'::jsonb, 0, 'C’est pourquoi une plume et une bille tombent ensemble dans le vide.', 5),
    ('3fd3c7c2-fe4f-5c07-9160-4e4c462d584d'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Le vecteur vitesse est tangent à la trajectoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il est orienté dans le sens du mouvement.', 6),
    ('f1d0a8db-2741-57c2-bb4f-d81df75a4433'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Que peut-on conclure si la somme des forces sur un système est nulle ?', 'mcq', '["Son centre de masse est immobile ou en mouvement rectiligne uniforme","Il est nécessairement immobile","Il accélère uniformément","Sa trajectoire est circulaire"]'::jsonb, 0, 'C’est le principe d’inertie, valable dans un référentiel galiléen.', 7),
    ('c96b4435-83e2-5059-ac19-d3a56bfd65e4'::uuid, 'b8c1e2d8-38ec-54ff-8a68-1368426564e4'::uuid, 'Une accélération peut être non nulle même si la valeur de la vitesse ne change pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un changement de DIRECTION suffit : c’est le cas du mouvement circulaire uniforme.', 8),
    ('7e769a09-3e7b-5df8-9141-54d7f59082a3'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'Comment varie la force gravitationnelle si la distance est doublée ?', 'mcq', '["Elle est divisée par quatre","Elle est divisée par deux","Elle est multipliée par deux","Elle est inchangée"]'::jsonb, 0, 'La force varie en 1 / d² : c’est une décroissance quadratique.', 1),
    ('7928c53f-67b6-5386-b7f0-20cb88fbafa5'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'L’interaction gravitationnelle peut-elle être répulsive ?', 'mcq', '["Non, elle est toujours attractive","Oui, entre deux masses opposées","Oui, à très courte distance","Oui, dans le vide"]'::jsonb, 0, 'C’est ce qui la distingue de l’interaction électrostatique.', 2),
    ('47360668-182a-5c32-a99f-ba9cfb50ed2a'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'Quelle est l’unité du champ de pesanteur g ?', 'mcq', '["Le newton par kilogramme","Le newton","Le kilogramme","Le joule"]'::jsonb, 0, 'Le N/kg, dimensionnellement équivalent au m/s².', 3),
    ('ba4dae0f-e3ce-594f-8579-327dd0b81735'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'La masse d’un astronaute change lorsqu’il se rend sur la Lune.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa MASSE est invariable ; c’est son POIDS qui est six fois plus faible.', 4),
    ('e325e3f0-c312-56a8-b8dd-6f09d9530c37'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'De quoi dépend la valeur du champ gravitationnel créé par un astre en un point ?', 'mcq', '["De la masse de l’astre et de la distance au point","De la masse du corps qui subit le champ","De la vitesse du corps","De la température de l’astre"]'::jsonb, 0, 'g = G × M / d², indépendamment du corps qui le subit.', 5),
    ('f9c7d3cc-a23e-5316-a921-12fc00cfee50'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'Le champ de pesanteur terrestre peut être considéré comme uniforme à l’échelle d’une salle de classe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Même valeur, même direction, même sens sur cette étendue.', 6),
    ('c52732d5-a0ed-5c03-98d4-7cc16277c197'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'Quelle relation lie le poids, la masse et le champ de pesanteur ?', 'mcq', '["P = m × g","P = m / g","P = g / m","P = m × g²"]'::jsonb, 0, 'Le poids est la force exercée par le champ sur la masse.', 7),
    ('da71d514-bd67-5e96-9df4-f997560f469a'::uuid, '84b0f605-a20b-57b4-9312-a47e3eb3107f'::uuid, 'Le champ gravitationnel est dirigé vers le centre de l’astre qui le crée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui donne à la verticale son sens physique.', 8),
    ('d8c390c2-35fb-514f-8b32-14f4e4835463'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Deux charges de même signe…', 'mcq', '["se repoussent","s’attirent","ne s’influencent pas","s’annulent"]'::jsonb, 0, 'C’est ce qui distingue l’interaction électrostatique de la gravitation, toujours attractive.', 1),
    ('6242e114-f978-527c-ba60-5c04e083449d'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Quelle est l’unité de charge électrique du Système international ?', 'mcq', '["Le coulomb","L’ampère","Le volt","Le farad"]'::jsonb, 0, 'La charge élémentaire vaut environ 1,6 × 10⁻¹⁹ C.', 2),
    ('ddab3a50-c80a-5779-b804-a056cc28194f'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'La loi de Coulomb a la même dépendance en distance que la loi de gravitation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Toutes deux varient en 1 / d², mais avec des intensités sans commune mesure.', 3),
    ('3e5d48f0-d398-5265-90c8-a3c840ba324b'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Quelle est la relation entre le champ électrique et la force subie par une charge q ?', 'mcq', '["F = q × E","F = E / q","F = q / E","F = q × E²"]'::jsonb, 0, 'La force est colinéaire au champ, de même sens si q est positive.', 4),
    ('f9f3c200-5b5f-5258-9a6f-ec5102720c54'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Comment est le champ électrique entre les plaques d’un condensateur plan ?', 'mcq', '["Uniforme","Radial","Nul","Variable dans le temps"]'::jsonb, 0, 'Même valeur, même direction et même sens en tout point.', 5),
    ('b146f16d-3556-501a-a00c-b1e4e8e931b6'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Quelle relation donne la valeur du champ dans un condensateur plan ?', 'mcq', '["E = U / d","E = U × d","E = d / U","E = U × d²"]'::jsonb, 0, 'U est la tension entre les plaques, d leur distance.', 6),
    ('fbf90390-f602-5626-8944-c36e1566513b'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Une charge négative subit une force de même sens que le champ électrique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La force est alors de sens OPPOSÉ au champ.', 7),
    ('0389cc98-e84b-548a-a0ff-52ccd09557c9'::uuid, '9055732b-0acd-50aa-8f8b-e923d10bce38'::uuid, 'Comment sont orientées les lignes de champ autour d’une charge ponctuelle négative ?', 'mcq', '["Radiales et entrantes","Radiales et sortantes","Circulaires","Parallèles"]'::jsonb, 0, 'Le champ pointe vers la charge négative.', 8),
    ('4b70ce07-2260-540d-888b-636422d7eedb'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Que transporte une onde ?', 'mcq', '["De l’énergie, sans transport de matière","De la matière, sans énergie","De la matière et de l’énergie","Ni l’une ni l’autre"]'::jsonb, 0, 'Le bouchon sur l’eau oscille sur place au passage de la vague.', 1),
    ('0a9e81a1-21c0-526a-9a4e-abf86d6dcd12'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Le son peut-il se propager dans le vide ?', 'mcq', '["Non, c’est une onde mécanique","Oui, comme la lumière","Oui, mais plus lentement","Oui, s’il est très intense"]'::jsonb, 0, 'Une onde mécanique exige un milieu matériel.', 2),
    ('e2b34299-67d1-514b-a0be-6155ae1bfa4f'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Quelle relation lie longueur d’onde, célérité et fréquence ?', 'mcq', '["λ = v / f","λ = v × f","λ = f / v","λ = v + f"]'::jsonb, 0, 'Équivalente à λ = v × T, puisque f = 1 / T.', 3),
    ('c11a62bf-691f-5d3c-ac12-44a156200577'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'La fréquence d’une onde change quand elle passe d’un milieu à un autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est imposée par la source ; ce sont la célérité et la longueur d’onde qui changent.', 4),
    ('cc3b1c30-fc38-51c2-bb01-c19960bff5ff'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Une onde sonore dans l’air est…', 'mcq', '["longitudinale","transversale","électromagnétique","stationnaire"]'::jsonb, 0, 'La perturbation est parallèle à la direction de propagation.', 5),
    ('2dacf3b6-3703-5fe4-9c4d-8e93fab5e963'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Quelle est l’unité de la fréquence ?', 'mcq', '["Le hertz","La seconde","Le mètre","Le mètre par seconde"]'::jsonb, 0, '1 Hz = un motif par seconde.', 6),
    ('473608b5-4d74-59b8-a375-a84658c5a869'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Le son se propage plus vite dans l’acier que dans l’air.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ 5 000 m/s contre 340 m/s : la rigidité du milieu accélère la propagation.', 7),
    ('79c61e36-6eca-55ac-99a5-9491f081f497'::uuid, 'e733b1eb-f2ae-5289-a0af-a7e690387aac'::uuid, 'Comment calcule-t-on le retard entre deux points distants de d ?', 'mcq', '["τ = d / v","τ = d × v","τ = v / d","τ = d × f"]'::jsonb, 0, 'C’est ce calcul qui permet de situer un orage.', 8),
    ('b4c93e01-c3d4-5b43-af02-abe894a8a857'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Quel est le domaine approximatif de la lumière visible ?', 'mcq', '["De 400 à 800 nm","De 10 à 400 nm","De 800 nm à 1 mm","Au-delà du mètre"]'::jsonb, 0, 'Du violet au rouge, une bande minuscule du spectre total.', 1),
    ('43a40158-98ec-59e7-87fa-1729af00350c'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Les ondes électromagnétiques ont-elles besoin d’un milieu matériel ?', 'mcq', '["Non, elles se propagent dans le vide","Oui, comme le son","Oui, sauf la lumière","Uniquement les rayons X"]'::jsonb, 0, 'C’est ce qui permet à la lumière des étoiles de nous parvenir.', 2),
    ('7155ed0f-4ec6-5414-92d8-1618309c4088'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Quel rayonnement est plus énergétique que la lumière visible ?', 'mcq', '["L’ultraviolet","L’infrarouge","Les micro-ondes","Les ondes radio"]'::jsonb, 0, 'Plus la fréquence est élevée, plus l’énergie du rayonnement est grande.', 3),
    ('1cb9067d-4778-5e0f-96d9-acad7a4f4dee'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Un spectre de raies d’émission est caractéristique de l’élément qui l’émet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une signature, qui permet d’identifier la composition d’une étoile.', 4),
    ('17eefe31-1240-54de-a299-80144a4c9259'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Qu’observe-t-on dans un spectre d’absorption ?', 'mcq', '["Des raies noires sur un fond continu","Des raies colorées sur fond noir","Un fond uniformément noir","Un spectre continu sans particularité"]'::jsonb, 0, 'Le gaz froid absorbe exactement les longueurs d’onde qu’il émettrait.', 5),
    ('ab42b397-3f1a-5e82-9afb-3d06a7768535'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'De quoi dépend la répartition d’un spectre continu d’émission ?', 'mcq', '["De la température du corps","De sa composition chimique","De sa masse","De sa distance"]'::jsonb, 0, 'Plus le corps est chaud, plus le maximum se décale vers le bleu.', 6),
    ('6aaacc40-bc59-500f-ad52-e4aa537f7834'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'Les micro-ondes ont une longueur d’onde plus courte que les ondes radio.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Du millimètre au décimètre, contre plus d’un mètre pour les ondes radio.', 7),
    ('fde720d3-144c-5d68-b6a6-fb5225e80b8f'::uuid, 'fda3316c-1f28-558d-a9ba-28b9460cbe4b'::uuid, 'À quelle vitesse une onde électromagnétique se propage-t-elle dans le vide ?', 'mcq', '["Environ 3,00 × 10⁸ m/s","Environ 340 m/s","Environ 1 500 m/s","Elle varie selon la fréquence"]'::jsonb, 0, 'C’est la même pour toutes les ondes du spectre.', 8),
    ('5404bbbb-6256-5b16-9239-88b892c012b9'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Quelle relation donne l’énergie d’un photon ?', 'mcq', '["E = h × f","E = h / f","E = h × λ","E = f / h"]'::jsonb, 0, 'Équivalente à E = h × c / λ.', 1),
    ('7d028c7c-dbc7-5e61-8660-c45729303850'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Un photon bleu est plus énergétique qu’un photon rouge.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa longueur d’onde est plus courte, donc sa fréquence et son énergie plus grandes.', 2),
    ('c9b1ea23-db24-56f5-a477-75ecf0a95971'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Que signifie « l’énergie d’un atome est quantifiée » ?', 'mcq', '["Elle ne peut prendre que certaines valeurs déterminées","Elle peut prendre n’importe quelle valeur","Elle est toujours nulle","Elle augmente continûment avec la température"]'::jsonb, 0, 'D’où la représentation en niveaux discrets.', 3),
    ('788ea61d-1b7d-572a-8f8e-b492982842c7'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'À quelle condition un atome absorbe-t-il un photon ?', 'mcq', '["Si l’énergie du photon correspond exactement à un écart entre deux niveaux","Si le photon est assez énergétique","Si le photon est visible","Toujours"]'::jsonb, 0, 'Un photon d’énergie intermédiaire n’est pas absorbé du tout.', 4),
    ('18b307f2-8f6a-5f03-859e-581409442043'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Combien vaut approximativement un électronvolt en joules ?', 'mcq', '["1,60 × 10⁻¹⁹ J","6,63 × 10⁻³⁴ J","3,00 × 10⁸ J","9,00 × 10⁹ J"]'::jsonb, 0, 'Unité commode à l’échelle atomique, où le joule est démesuré.', 5),
    ('5df7c1d0-2585-554e-b491-a24bae9cd932'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Comment appelle-t-on le niveau d’énergie le plus bas d’un atome ?', 'mcq', '["L’état fondamental","L’état excité","L’état ionisé","L’état stationnaire"]'::jsonb, 0, 'Les niveaux supérieurs sont les états excités.', 6),
    ('d31d2405-99df-5810-9cda-17d85c8a80ea'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Un atome excité qui se désexcite émet un photon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son énergie vaut exactement la différence entre les deux niveaux.', 7),
    ('5d0fe49a-47d2-55d8-8e10-ab1aa3ed2eed'::uuid, '3930af16-fea5-54c4-8209-03d2799ecf67'::uuid, 'Pourquoi les spectres de raies sont-ils caractéristiques d’un élément ?', 'mcq', '["Parce que ses écarts entre niveaux d’énergie lui sont propres","Parce que sa température est unique","Parce que sa masse est unique","Parce qu’il émet toutes les longueurs d’onde"]'::jsonb, 0, 'Chaque raie correspond à une transition entre deux niveaux donnés.', 8),
    ('526e0430-72a0-5efe-8248-17e60a9fe3c5'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Quelle est l’unité de la vergence d’une lentille ?', 'mcq', '["La dioptrie","Le mètre","Le lumen","Le hertz"]'::jsonb, 0, 'La vergence est l’inverse de la distance focale exprimée en mètres.', 1),
    ('e6a9f362-1719-58d4-8c16-a880e408714d'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Quelle est la distance focale d’une lentille de vergence 5 dioptries ?', 'mcq', '["0,20 m","5 m","0,05 m","2 m"]'::jsonb, 0, 'f’ = 1 / C = 1 / 5 = 0,20 m.', 2),
    ('b3785a6e-951b-5d96-b581-84301e68d793'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Un rayon passant par le centre optique d’une lentille mince n’est pas dévié.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des trois rayons particuliers utilisés en construction.', 3),
    ('c466a046-f013-5870-aa20-ea65ebdf68c6'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Que devient un rayon parallèle à l’axe optique après la lentille convergente ?', 'mcq', '["Il passe par le foyer image F’","Il reste parallèle à l’axe","Il passe par le centre optique","Il est réfléchi"]'::jsonb, 0, 'C’est la définition même du foyer image.', 4),
    ('cf48b0ab-2036-5993-9630-c18dfd136d64'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Que signifie un grandissement négatif ?', 'mcq', '["L’image est renversée","L’image est réduite","L’image est virtuelle","L’image est floue"]'::jsonb, 0, 'Le signe donne le sens, la valeur absolue la taille.', 5),
    ('85053d2b-26cf-519a-bb1e-5c1869549901'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Une image virtuelle peut être recueillie sur un écran.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule une image RÉELLE peut l’être ; la virtuelle s’observe à travers la lentille.', 6),
    ('ff1b88e7-b43f-5a34-9aa6-a986de1601a3'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Où placer un objet pour obtenir une image virtuelle, droite et agrandie ?', 'mcq', '["Entre le centre optique et le foyer objet","Au-delà de 2f’","Exactement au foyer objet","À l’infini"]'::jsonb, 0, 'C’est le fonctionnement de la loupe.', 7),
    ('228f7c1d-f643-58f1-be23-6a0107b985ab'::uuid, 'a2c6229e-e57e-5ef6-a25f-1c915bbc6353'::uuid, 'Plus la vergence d’une lentille est grande, plus sa distance focale est petite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont inverses l’une de l’autre.', 8),
    ('0c39cec9-ca99-5d1e-9b95-c837d1f9c46c'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Quelles sont les trois couleurs primaires de la synthèse additive ?', 'mcq', '["Rouge, vert, bleu","Cyan, magenta, jaune","Rouge, jaune, bleu","Vert, orange, violet"]'::jsonb, 0, 'Leur superposition donne du blanc : c’est le principe des écrans.', 1),
    ('97a3dcc2-c881-52c4-93fb-3c4d9970e0b3'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'La superposition des trois primaires de la synthèse soustractive donne du blanc.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle donne du NOIR : chaque matière retranche des longueurs d’onde.', 2),
    ('d85f00ba-3d68-50c7-b6cd-29a821a00822'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'De quelle couleur apparaît un pull rouge éclairé en lumière verte ?', 'mcq', '["Noir","Rouge","Vert","Jaune"]'::jsonb, 0, 'Il n’a aucune lumière rouge à diffuser, et absorbe le vert.', 3),
    ('502b2582-4d3f-50cc-b26c-0131eedb377b'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Quelle est la couleur complémentaire du bleu ?', 'mcq', '["Le jaune","Le rouge","Le vert","Le magenta"]'::jsonb, 0, 'Leur superposition en synthèse additive donne du blanc.', 4),
    ('b9c12410-328a-5485-9fbb-c9198d61caed'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Un objet opaque apparaît de la couleur qu’il diffuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il absorbe les autres longueurs d’onde du spectre incident.', 5),
    ('74778e4b-4553-5785-a763-a296445ac14c'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Quelles cellules de la rétine permettent la vision des couleurs ?', 'mcq', '["Les cônes","Les bâtonnets","Les neurones du nerf optique","Les cellules du cristallin"]'::jsonb, 0, 'Trois types de cônes, sensibles au rouge, au vert et au bleu.', 6),
    ('cbf0ef9c-a3f3-5496-99f7-cec209b679aa'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Pourquoi la vision nocturne se fait-elle en niveaux de gris ?', 'mcq', '["Parce que seuls les bâtonnets, insensibles à la couleur, restent actifs","Parce que les objets perdent leur couleur","Parce que le cristallin se déforme","Parce que la lumière change de nature"]'::jsonb, 0, 'Les bâtonnets sont très sensibles mais ne distinguent pas les couleurs.', 7),
    ('b17e5cbf-64c5-5555-b7ce-a1698d33f1a3'::uuid, '9cc5b6e1-11a4-5825-96bf-76a0b288a550'::uuid, 'Une solution colorée absorbe la couleur complémentaire de celle qu’elle paraît avoir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une solution bleue absorbe dans le jaune-orangé : c’est la base de la spectrophotométrie.', 8),
    ('d9cd28c1-205e-5707-b61e-aa25bbc9d5c3'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Quelle est l’expression de l’énergie cinétique ?', 'mcq', '["Ec = ½ × m × v²","Ec = m × g × z","Ec = m × v","Ec = ½ × m × v"]'::jsonb, 0, 'Elle croît avec le carré de la vitesse.', 1),
    ('7d0d1c5c-390f-582d-a77a-828511d9be1c'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Que devient l’énergie cinétique d’un véhicule dont la vitesse double ?', 'mcq', '["Elle est multipliée par quatre","Elle est doublée","Elle est multipliée par huit","Elle est inchangée"]'::jsonb, 0, 'La dépendance en v² est l’argument physique des limitations de vitesse.', 2),
    ('31e766b2-54e2-56c4-a3d4-c7b6b80e1f40'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'L’énergie potentielle de pesanteur dépend du choix de l’origine des altitudes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seules ses VARIATIONS ont un sens physique.', 3),
    ('74991067-bf1f-5520-851e-b6f6db03fa7b'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Que dit le théorème de l’énergie cinétique ?', 'mcq', '["La variation d’énergie cinétique égale la somme des travaux des forces","L’énergie mécanique se conserve toujours","Le travail est nul pour toute force","L’énergie cinétique est constante"]'::jsonb, 0, 'ΔEc = Σ W(F) entre les deux points considérés.', 4),
    ('58e83fa9-5f34-5897-9a9a-5ffd92b8c772'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Une force perpendiculaire au déplacement ne travaille pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'W = F × d × cos α, et cos 90° = 0.', 5),
    ('092071bf-053a-5df6-b4a0-930bb4a461b6'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Dans quel cas l’énergie mécanique se conserve-t-elle ?', 'mcq', '["Quand seules des forces conservatives travaillent","Quand la vitesse est constante","Quand l’altitude est constante","Toujours"]'::jsonb, 0, 'Les frottements, eux, la font diminuer.', 6),
    ('c527e26a-ab22-5db4-b85f-e288940d0639'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Que devient l’énergie mécanique dissipée par les frottements ?', 'mcq', '["Elle est transférée au milieu sous forme thermique","Elle disparaît","Elle se transforme en énergie potentielle","Elle augmente l’énergie cinétique"]'::jsonb, 0, 'Elle est dégradée, non détruite : le premier principe reste vrai.', 7),
    ('c0cb328b-3526-5718-8e71-c7d539662e79'::uuid, '90ba3c50-d70a-5f54-8901-c34c674bfe36'::uuid, 'Sans frottement, la vitesse en bas d’un toboggan dépend de la forme de la piste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne dépend que de la dénivellation, par conservation de l’énergie mécanique.', 8),
    ('53d6babe-1e25-58b6-b8ca-ada906c44817'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Quelle relation donne la puissance électrique d’un dipôle ?', 'mcq', '["P = U × I","P = U / I","P = U + I","P = U × I²"]'::jsonb, 0, 'Avec U en volts et I en ampères, P est en watts.', 1),
    ('501ef0fc-ce26-5264-bfbd-8624d6f36b00'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Quelle est l’expression de la puissance dissipée par effet Joule ?', 'mcq', '["P = R × I²","P = R × I","P = R / I","P = I / R"]'::jsonb, 0, 'Elle varie avec le CARRÉ de l’intensité.', 2),
    ('9630c006-48cd-5a7d-8db9-eb6e609e420c'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Pourquoi transporte-t-on l’électricité à très haute tension ?', 'mcq', '["Pour réduire l’intensité, donc les pertes par effet Joule","Pour augmenter la puissance transportée","Pour diminuer la résistance des câbles","Pour éviter les courts-circuits"]'::jsonb, 0, 'À puissance donnée, augmenter U diminue I, et les pertes varient en I².', 3),
    ('8fc8e293-5965-5d9f-974e-516e679abb4c'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Un rendement peut-il dépasser 1 ?', 'mcq', '["Non, jamais","Oui, pour un générateur","Oui, avec une LED","Oui, en régime transitoire"]'::jsonb, 0, 'L’énergie utile ne peut excéder l’énergie reçue.', 4),
    ('41306b55-a8f8-566f-bc3d-16727abf1249'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Combien de joules vaut un kilowattheure ?', 'mcq', '["3,6 × 10⁶ J","1 000 J","3 600 J","10⁹ J"]'::jsonb, 0, '1 kW pendant 3 600 s.', 5),
    ('b56664c7-4f12-516b-b515-41bfdaf9200a'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'La résistance interne d’un générateur fait chuter la tension à ses bornes quand le courant augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'U = E − r × I : la chute est proportionnelle à l’intensité.', 6),
    ('41f9a4c8-9c48-56c9-9ad0-2acdad03d0c7'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'Que dit la loi d’Ohm pour un conducteur ohmique ?', 'mcq', '["U = R × I","U = R / I","U = I / R","U = R × I²"]'::jsonb, 0, 'La tension est proportionnelle à l’intensité qui le traverse.', 7),
    ('1b68c203-57e7-58b1-a74d-f39b043f738e'::uuid, '89b13702-2232-5218-8642-d2a2df3df4ee'::uuid, 'L’effet Joule est toujours un phénomène nuisible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est recherché dans un radiateur ou un grille-pain, subi ailleurs.', 8),
    ('fa998f6d-cc34-58e7-9bdb-ee6ac1ab2029'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Combien d’entités contient une mole ?', 'mcq', '["Environ 6,02 × 10²³","Environ 3,00 × 10⁸","Environ 1,60 × 10⁻¹⁹","Environ 6,63 × 10⁻³⁴"]'::jsonb, 0, 'C’est la constante d’Avogadro.', 1),
    ('d0edb441-7533-5fe7-a59c-f55518ebd1fe'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Quelle relation lie quantité de matière, masse et masse molaire ?', 'mcq', '["n = m / M","n = m × M","n = M / m","n = m + M"]'::jsonb, 0, 'La masse molaire s’exprime en g/mol.', 2),
    ('a2f69def-78e3-567a-afa9-37c1c7a58078'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Le volume molaire d’un gaz dépend de la nature de ce gaz.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Dans les mêmes conditions de température et de pression, il est le même pour tous les gaz.', 3),
    ('72da8d17-2053-5e7b-8600-00f9acde8f2f'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Quelle est la masse molaire de l’eau H₂O ?', 'mcq', '["18,0 g/mol","16,0 g/mol","20,0 g/mol","2,0 g/mol"]'::jsonb, 0, '2 × 1,0 pour l’hydrogène + 16,0 pour l’oxygène.', 4),
    ('d5428f57-9563-5a40-9208-8a2c22783266'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Quelle relation utilise-t-on pour une dilution ?', 'mcq', '["C(mère) × V(prélevé) = C(fille) × V(fille)","C(mère) × V(fille) = C(fille) × V(prélevé)","C(mère) + C(fille) = V","C(mère) / V(prélevé) = C(fille) × V(fille)"]'::jsonb, 0, 'La quantité de soluté prélevée est conservée.', 5),
    ('7efd5427-247b-5514-b4f7-0757544dcbf8'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Une dilution modifie la quantité de matière de soluté prélevée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle la conserve : seul le volume de solvant change.', 6),
    ('5ddfa066-d682-55db-a82f-cb8405671473'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Comment passe-t-on de la concentration molaire à la concentration en masse ?', 'mcq', '["En multipliant par la masse molaire","En divisant par la masse molaire","En multipliant par le volume","En multipliant par la constante d’Avogadro"]'::jsonb, 0, 't = C × M, en g/L.', 7),
    ('70bde51a-d133-51df-af7b-0bed1f7aa8e7'::uuid, '898af7cf-ebda-5de6-b49f-11eae5d8c9d6'::uuid, 'Quelle relation donne la quantité de matière d’un soluté en solution ?', 'mcq', '["n = C × V","n = C / V","n = V / C","n = C × M"]'::jsonb, 0, 'Avec C en mol/L et V en litres.', 8),
    ('e6131c29-2047-5f7e-9cf8-3123206da961'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'Quelle est l’unité de l’absorbance ?', 'mcq', '["Elle n’a pas d’unité","Le mol/L","Le mètre","Le hertz"]'::jsonb, 0, 'C’est une grandeur sans dimension.', 1),
    ('c3d4858a-46fb-51a3-aab8-69ba7d72ef83'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'Que dit la loi de Beer-Lambert ?', 'mcq', '["L’absorbance est proportionnelle à la concentration, pour une solution diluée","L’absorbance est inversement proportionnelle à la concentration","L’absorbance dépend uniquement du volume","L’absorbance est constante"]'::jsonb, 0, 'A = k × C, à longueur d’onde et cuve fixées.', 2),
    ('2c770d2e-c1a4-5bc6-bd8c-bb7f51cc9bbf'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'À quelle longueur d’onde faut-il régler le spectrophotomètre ?', 'mcq', '["À λ(max), le maximum d’absorption de l’espèce étudiée","À 400 nm systématiquement","À la couleur de la solution","À n’importe quelle longueur d’onde"]'::jsonb, 0, 'C’est là que la mesure est la plus sensible et la plus précise.', 3),
    ('75e5413b-8cc6-5647-8397-42a92c757620'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'Une solution bleue absorbe principalement dans le bleu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle absorbe la couleur COMPLÉMENTAIRE, le jaune-orangé.', 4),
    ('361ed86c-10aa-57b5-9cd0-febdc5376026'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'À quoi sert le « blanc » avant une série de mesures ?', 'mcq', '["À ne mesurer que l’absorption de l’espèce étudiée, sans celle du solvant et de la cuve","À nettoyer l’appareil","À vérifier la couleur de la solution","À diluer les étalons"]'::jsonb, 0, 'Il fixe le zéro de l’appareil.', 5),
    ('addf2da1-d591-54d4-8065-e8ccce3425da'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'La droite d’étalonnage A = f(C) passe par l’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une solution de concentration nulle n’absorbe rien.', 6),
    ('48312489-889a-5f59-9f08-8a021abb63be'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'La loi de Beer-Lambert reste valable pour une solution très concentrée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La proportionnalité se perd : la courbe s’incurve, il faut diluer.', 7),
    ('61305346-a781-5a94-a455-ee9047a08504'::uuid, '8a2068f9-fea9-5943-a785-7b701f0033da'::uuid, 'Comment prépare-t-on une gamme d’étalons ?', 'mcq', '["Par dilutions successives d’une solution mère de concentration connue","Par évaporation du solvant","Par mélange de solutions inconnues","Par chauffage progressif"]'::jsonb, 0, 'Chaque étalon a une concentration parfaitement connue.', 8),
    ('853d0100-6a12-550b-a21b-2edc6caeb312'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Que mesure l’avancement d’une réaction ?', 'mcq', '["Le degré de progression de la réaction, en moles","La masse de produit formé","La vitesse de la réaction","La concentration des réactifs"]'::jsonb, 0, 'Il vaut 0 à l’état initial et x(max) à l’état final.', 1),
    ('c8b2e905-42a9-524d-96a4-63cb1fec62cb'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Comment identifie-t-on le réactif limitant ?', 'mcq', '["En comparant les rapports n(initial) divisé par le coefficient stœchiométrique","En prenant celui dont la quantité initiale est la plus faible","En prenant celui de plus grande masse molaire","En prenant celui qui est en solution"]'::jsonb, 0, 'Le plus petit rapport désigne le limitant.', 2),
    ('da117f3a-03d1-53df-9b0c-ea22a95d3f52'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Le réactif limitant est toujours celui dont la quantité initiale est la plus faible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est faux dès que les coefficients stœchiométriques diffèrent.', 3),
    ('3f5b629e-a825-5dab-a35d-7c32d96457eb'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Comment évolue la quantité d’un produit avec l’avancement ?', 'mcq', '["Elle augmente de coefficient × x","Elle diminue de coefficient × x","Elle reste constante","Elle est proportionnelle à 1 / x"]'::jsonb, 0, 'Les réactifs, eux, voient leur quantité diminuer.', 4),
    ('e0b979fd-78d7-52de-b0f6-2915e1d8a90d'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Qu’est-ce qu’un mélange stœchiométrique ?', 'mcq', '["Un mélange où tous les réactifs sont épuisés simultanément","Un mélange où un réactif est en excès","Un mélange de volumes égaux","Un mélange de masses égales"]'::jsonb, 0, 'Tous les rapports n(initial) / coefficient sont alors égaux.', 5),
    ('b0b0e52a-751d-5820-8696-d8caffd6bfb5'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Une équation de réaction doit conserver les atomes et la charge.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la double condition d’un ajustement correct.', 6),
    ('a6a43f42-d724-5e99-a82c-6a22f62a8cdf'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Que vaut l’avancement à l’état initial ?', 'mcq', '["0","1","x(max)","La quantité du réactif limitant"]'::jsonb, 0, 'Il croît ensuite au fur et à mesure de la transformation.', 7),
    ('9b462b7d-1f87-5e42-8fa7-e9907befa8bf'::uuid, '1f80321b-7021-5487-831a-b70d2950de67'::uuid, 'Comment convertit-on une quantité de matière de gaz en volume ?', 'mcq', '["V = n × V(m)","V = n / V(m)","V = n × M","V = n × C"]'::jsonb, 0, 'V(m) vaut environ 24 L/mol dans les conditions usuelles.', 8),
    ('e939643d-3fbe-585a-800a-d03244721ae5'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Qu’est-ce que l’équivalence d’un titrage ?', 'mcq', '["L’instant où les réactifs ont été mélangés dans les proportions stœchiométriques","L’instant où la solution devient neutre","L’instant où la burette est vide","L’instant où la couleur disparaît totalement"]'::jsonb, 0, 'Avant, le titrant est limitant ; après, c’est le titré qui a disparu.', 1),
    ('394cddc7-3c4e-572c-8b3e-7160b4fc95b9'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Quelle qualité la réaction support d’un titrage doit-elle avoir ?', 'mcq', '["Être totale, rapide et unique","Être lente et réversible","Être exothermique","Produire un gaz"]'::jsonb, 0, 'Sans quoi la relation à l’équivalence ne serait pas exploitable.', 2),
    ('02dd82f6-d517-5fa8-93d7-3338412aa9ff'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Ajouter de l’eau distillée dans le bécher fausse le résultat d’un titrage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La QUANTITÉ de matière titrée est inchangée : seule la concentration momentanée varie.', 3),
    ('40a1ee47-74d9-52f0-9e08-dce41ef08c19'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Comment repère-t-on l’équivalence dans un titrage conductimétrique ?', 'mcq', '["À l’intersection des deux droites de la courbe","Au maximum de conductivité","Au changement de couleur","Au point où la conductivité s’annule"]'::jsonb, 0, 'La conductivité varie linéairement de part et d’autre.', 4),
    ('c697029b-9772-5a6e-bb2e-4e96d845251b'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Avec quel instrument prélève-t-on le réactif titré ?', 'mcq', '["La pipette jaugée","La burette graduée","L’éprouvette graduée","Le bécher"]'::jsonb, 0, 'C’est l’instrument de prélèvement le plus précis.', 5),
    ('93e0ef48-6fc2-5b96-95ed-a452e95acf8f'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Dans un titrage pH-métrique, l’équivalence correspond au saut de pH.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On la repère au point d’inflexion, par la méthode des tangentes.', 6),
    ('75c267b8-23fc-5979-970c-b7ed5c91760f'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Que devient le réactif titrant après l’équivalence ?', 'mcq', '["Il s’accumule dans le mélange","Il est totalement consommé","Il précipite","Il se décompose"]'::jsonb, 0, 'C’est ce qui rend visible le changement de couleur persistant.', 7),
    ('b1703042-0586-5bc8-9b93-8bc5b782f1f5'::uuid, 'e2031d11-97ef-5d9f-9d92-e9a437263537'::uuid, 'Les coefficients stœchiométriques interviennent-ils dans la relation à l’équivalence ?', 'mcq', '["Oui, dès qu’ils diffèrent de 1","Non, jamais","Uniquement en colorimétrie","Uniquement si un gaz se forme"]'::jsonb, 0, 'Les oublier est l’erreur la plus fréquente en devoir.', 8),
    ('bcb5108e-b675-5d44-b86a-e25fa4ae24a6'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Que représente un schéma de Lewis ?', 'mcq', '["La répartition des électrons de valence dans une molécule","La position des noyaux atomiques","Le nombre de neutrons","L’énergie de la molécule"]'::jsonb, 0, 'Doublets liants et doublets non liants y figurent.', 1),
    ('c2784e30-843c-51d3-9c1b-ca85074faf9b'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Combien de liaisons le carbone forme-t-il habituellement ?', 'mcq', '["Quatre","Deux","Trois","Une"]'::jsonb, 0, 'Avec quatre électrons de valence, il complète son octet par quatre liaisons.', 2),
    ('7880b363-5fb4-5a68-bd33-a29889caa072'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Combien de doublets non liants porte l’atome d’oxygène dans l’eau ?', 'mcq', '["Deux","Un","Trois","Aucun"]'::jsonb, 0, 'Deux liaisons et deux doublets non liants : six électrons de valence.', 3),
    ('ffa6445f-029a-5358-9d12-5234f7005d09'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'La règle de l’octet s’applique à l’hydrogène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’hydrogène suit la règle du DUET : deux électrons.', 4),
    ('c5cc0d20-d852-5dd6-9d9c-fd429d928461'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Pourquoi la molécule d’eau est-elle coudée ?', 'mcq', '["Parce que les deux doublets non liants de l’oxygène repoussent les liaisons","Parce que l’hydrogène est petit","Parce qu’elle est polaire","Parce qu’elle est liquide"]'::jsonb, 0, 'La répulsion entre doublets impose la géométrie.', 5),
    ('3c54e324-7b9f-533b-8d10-22f781aee336'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Combien d’électrons de valence possède l’azote ?', 'mcq', '["Cinq","Trois","Quatre","Six"]'::jsonb, 0, 'Il forme donc trois liaisons et porte un doublet non liant.', 6),
    ('3b203e2b-bfdf-5bd2-8600-26d1ca6e0b4d'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Un doublet non liant participe à une liaison entre deux atomes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il appartient à un seul atome ; seul le doublet LIANT est partagé.', 7),
    ('f0d8895a-da58-52eb-90d4-18e25409207a'::uuid, '307f734e-69bf-5667-ac8d-f2f5eb08dea4'::uuid, 'Que faire si un atome reste incomplet après avoir placé les liaisons simples ?', 'mcq', '["Former une liaison double ou triple","Ajouter un atome d’hydrogène","Retirer un doublet non liant","Ioniser la molécule"]'::jsonb, 0, 'C’est l’étape finale de la construction d’un schéma de Lewis.', 8),
    ('aecb64a5-253b-5c4f-9cf5-597adb296337'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Que mesure l’électronégativité ?', 'mcq', '["La tendance d’un atome à attirer les électrons d’une liaison","La charge d’un ion","Le nombre d’électrons de valence","L’énergie d’ionisation"]'::jsonb, 0, 'Elle décide de la polarisation des liaisons.', 1),
    ('85b76494-011f-5476-8a81-911ad1d891c1'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Quel est l’élément le plus électronégatif ?', 'mcq', '["Le fluor","L’oxygène","L’azote","Le chlore"]'::jsonb, 0, 'Suivi de l’oxygène, de l’azote et du chlore.', 2),
    ('408ee1ee-f79c-5ea8-9aaf-cc762140d147'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'La liaison dans la molécule de dioxygène O₂ est polarisée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les deux atomes sont identiques : aucun ne l’emporte.', 3),
    ('10bacfc1-0608-5868-85cf-d7aca2383b63'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'La molécule de dioxyde de carbone CO₂ est-elle polaire ?', 'mcq', '["Non, sa géométrie linéaire compense les polarités","Oui, car ses liaisons sont polarisées","Oui, car elle contient de l’oxygène","Non, car ses liaisons ne sont pas polarisées"]'::jsonb, 0, 'La géométrie compte autant que l’électronégativité.', 4),
    ('44f23943-90a6-5e45-9da4-118263446c77'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Que signifie la notation δ− sur un atome ?', 'mcq', '["Il porte une charge partielle négative","Il porte une charge entière négative","Il a perdu un électron","Il est un anion"]'::jsonb, 0, 'Ce sont des charges PARTIELLES, non des ions.', 5),
    ('3b472d72-d2e3-5fca-8144-5988c17dc3c1'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Comment varie l’électronégativité de gauche à droite dans une période ?', 'mcq', '["Elle augmente","Elle diminue","Elle reste constante","Elle varie sans règle"]'::jsonb, 0, 'Et elle diminue de haut en bas dans une colonne.', 6),
    ('93dcc3a0-4cdc-54ef-add2-de167a79a7aa'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'Un soluté polaire se dissout mieux dans un solvant polaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le principe « semblable dissout semblable ».', 7),
    ('b1aac123-fa98-5a83-a0a7-ee97cbaba71d'::uuid, 'a0ed6412-e31b-560e-96b7-5cd43179c98a'::uuid, 'À masse molaire comparable, une molécule polaire bout à plus haute température qu’une apolaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les interactions entre molécules polaires sont plus fortes à rompre.', 8),
    ('165d9daa-5205-54cc-be98-2a743fb72c37'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Quelle liaison est rompue lors d’une réaction chimique ?', 'mcq', '["La liaison covalente","La liaison hydrogène","L’interaction de Van der Waals","Aucune"]'::jsonb, 0, 'Les interactions faibles, elles, sont rompues lors des changements d’état.', 1),
    ('72951915-4982-5fb1-9a5d-60f8cec9717c'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'La vaporisation d’un corps moléculaire rompt des liaisons covalentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne rompt que les interactions ENTRE molécules.', 2),
    ('2c0a901e-f798-516e-96a7-46a6cd8b09c2'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Entre quels atomes s’établit une liaison hydrogène ?', 'mcq', '["Un hydrogène lié à O, N ou F et un atome électronégatif porteur d’un doublet non liant","Deux atomes de carbone","Deux ions de charges opposées","Deux hydrogènes"]'::jsonb, 0, 'Elle exige un atome très électronégatif des deux côtés.', 3),
    ('1db5a97c-c64a-5414-b269-082c74a911a1'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Pourquoi la température d’ébullition croît-elle avec la longueur d’une chaîne carbonée ?', 'mcq', '["Parce que les interactions de Van der Waals augmentent avec la taille","Parce que les liaisons covalentes se renforcent","Parce que la masse volumique augmente","Parce que la molécule devient polaire"]'::jsonb, 0, 'Plus de contacts entre molécules, donc plus d’énergie à fournir.', 4),
    ('cf75a7b8-284b-5162-873c-a20820e93951'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Les interactions de Van der Waals n’existent qu’entre molécules polaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles existent entre TOUTES les molécules, et se renforcent avec la polarité.', 5),
    ('a580f787-79a2-5fd5-a35f-ce238dcb4952'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Qu’est-ce que la solvatation ?', 'mcq', '["L’entourage d’un ion par les molécules de solvant orientées","La dissociation d’un solide ionique","L’évaporation du solvant","La formation d’un précipité"]'::jsonb, 0, 'C’est la deuxième étape de la dissolution.', 6),
    ('f6f0b1da-b307-5c93-b562-71791c49b580'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Pourquoi l’eau est-elle liquide à température ambiante malgré sa faible masse molaire ?', 'mcq', '["À cause des liaisons hydrogène entre ses molécules","À cause de sa masse volumique","À cause de sa géométrie linéaire","À cause de ses liaisons covalentes"]'::jsonb, 0, 'Sans elles, elle serait gazeuse comme le sulfure d’hydrogène.', 7),
    ('35ae4dfc-c4bd-54af-8deb-71235122e185'::uuid, '9321749a-89be-52e4-b452-061d765aedea'::uuid, 'Un solide ionique est électriquement neutre dans son ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les charges des cations et des anions s’y compensent exactement.', 8),
    ('b07e6406-1c0a-54ca-873b-c272324aed95'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Qu’est-ce qu’une solution saturée ?', 'mcq', '["Une solution qui a atteint la solubilité maximale de l’espèce dissoute","Une solution très diluée","Une solution colorée","Une solution chauffée"]'::jsonb, 0, 'Le surplus de soluté reste alors à l’état solide.', 1),
    ('14ed9cb8-d9d0-54e8-aaff-270c101e7b89'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Quelles conditions doit remplir un solvant extracteur ?', 'mcq', '["Mieux dissoudre l’espèce et être non miscible au solvant de départ","Être plus dense que l’eau","Être coloré","Être miscible au solvant de départ"]'::jsonb, 0, 'Sans non-miscibilité, aucune séparation de phases n’est possible.', 2),
    ('5ce42977-1c27-5d1b-8d4b-0f9ca2ae9871'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'La solubilité d’un gaz augmente avec la température.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle DIMINUE : une boisson gazeuse se dégaze en se réchauffant.', 3),
    ('65ec9bc6-9d6c-5e06-b6a1-438eb423ff37'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Quel matériel utilise-t-on pour une extraction liquide-liquide ?', 'mcq', '["L’ampoule à décanter","La burette graduée","Le réfrigérant à boules","La fiole jaugée"]'::jsonb, 0, 'Elle permet d’agiter puis de soutirer la phase du bas.', 4),
    ('3c142d3a-fa06-555c-ba23-f3709840c468'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Comment savoir quelle phase se trouve au-dessus dans l’ampoule à décanter ?', 'mcq', '["En comparant les masses volumiques : la moins dense surnage","En comparant les couleurs","En comparant les volumes","La phase aqueuse est toujours en bas"]'::jsonb, 0, 'Le dichlorométhane passe sous l’eau, l’éther au-dessus.', 5),
    ('809de7a5-3f49-5b81-88e3-a712246a98a0'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Pourquoi faut-il dégazer pendant l’agitation ?', 'mcq', '["Parce que l’agitation libère des vapeurs qui font monter la pression","Pour mieux mélanger les phases","Pour accélérer la décantation","Pour refroidir le mélange"]'::jsonb, 0, 'Sans dégazage, le bouchon peut être expulsé.', 6),
    ('ef7f54ce-9500-5163-91b2-39ea9003763a'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'Une espèce apolaire se dissout mieux dans le cyclohexane que dans l’eau.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Semblable dissout semblable : le cyclohexane est apolaire.', 7),
    ('7184abfa-fb57-5cde-84b7-966df86dd8ce'::uuid, 'a3240b27-17d7-5473-8265-d0d35cf30a76'::uuid, 'À quoi sert une chromatographie sur couche mince après une synthèse ?', 'mcq', '["À vérifier la pureté du produit obtenu","À mesurer sa masse","À le purifier par distillation","À déterminer sa concentration"]'::jsonb, 0, 'L’espèce se partage entre une phase fixe et une phase mobile.', 8),
    ('f071ef49-7d14-5d31-a5ad-a74811fa0577'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Que représente chaque sommet d’une formule topologique ?', 'mcq', '["Un atome de carbone","Un atome d’hydrogène","Une liaison double","Un groupe fonctionnel"]'::jsonb, 0, 'Les hydrogènes portés par ces carbones ne sont pas écrits.', 1),
    ('0d3aa9e8-a80b-55f5-9026-ba573913145c'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Que sont deux isomères ?', 'mcq', '["Deux molécules de même formule brute et de structures différentes","Deux molécules identiques","Deux molécules de masses molaires différentes","Deux molécules du même groupe fonctionnel"]'::jsonb, 0, 'Leurs propriétés diffèrent, parfois beaucoup.', 2),
    ('2f338bb1-a7a9-5739-b521-984341ca6365'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Quelle terminaison caractérise un alcool ?', 'mcq', '["-ol","-al","-one","-ane"]'::jsonb, 0, '-al pour l’aldéhyde, -one pour la cétone, -ane pour l’alcane.', 3),
    ('7517f619-5f65-5f97-a07e-59873864dfd6'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Comment numérote-t-on la chaîne principale ?', 'mcq', '["De façon à obtenir les plus petits indices","Toujours de gauche à droite","En partant du carbone le plus ramifié","Dans le sens de l’écriture"]'::jsonb, 0, 'C’est la règle qui lève toute ambiguïté de nommage.', 4),
    ('ba42c3a3-a2cd-5d76-91c5-b630fcab0cd1'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Une formule brute renseigne sur l’enchaînement des atomes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne donne que le NOMBRE de chaque atome.', 5),
    ('fe703ab9-b093-5c3c-a326-e3cf5f4a31c0'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Quel préfixe correspond à une chaîne principale de cinq carbones ?', 'mcq', '["pent-","but-","hex-","prop-"]'::jsonb, 0, 'Méth-, éth-, prop-, but-, pent- : la série à connaître par cœur.', 6),
    ('6ab74315-d636-5f72-b423-e69127e58226'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'À nombre de carbones égal, un alcane ramifié bout plus bas qu’un alcane linéaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses molécules s’emboîtent moins bien : interactions de Van der Waals plus faibles.', 7),
    ('8618beb8-b90c-5dc9-9a34-459ad0465f3b'::uuid, 'be66ddee-819a-5948-8fa0-7e257c93699e'::uuid, 'Quelle terminaison caractérise un acide carboxylique ?', 'mcq', '["acide …-oïque","…-oate de …-yle","-amine","-ène"]'::jsonb, 0, 'L’ester, lui, se nomme …-oate de …-yle.', 8),
    ('42bc0807-2285-5218-ab5e-0f5311a3bd87'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'À quoi sert un chauffage à reflux ?', 'mcq', '["Chauffer pour accélérer la réaction sans perdre de matière","Refroidir le mélange réactionnel","Séparer deux liquides","Purifier un solide"]'::jsonb, 0, 'Le réfrigérant condense les vapeurs, qui retombent dans le ballon.', 1),
    ('688c8ace-dcbd-5849-a6e6-676802b40574'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Quels sont les deux facteurs cinétiques au programme ?', 'mcq', '["La température et la concentration des réactifs","La pression et le volume","La masse et la densité","Le pH et la couleur"]'::jsonb, 0, 'Un catalyseur accélère aussi, mais il n’est pas un facteur cinétique au même titre.', 2),
    ('8f0e7fd3-befb-5661-b432-d61ff125735a'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Un catalyseur modifie l’état final d’un système chimique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il accélère seulement l’évolution, sans être consommé.', 3),
    ('69e7829e-9f0c-54ad-a5e9-504760974ea1'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Quelle technique purifie un solide obtenu par synthèse ?', 'mcq', '["La recristallisation","La distillation fractionnée","L’extraction liquide-liquide","La chromatographie"]'::jsonb, 0, 'On dissout à chaud puis on laisse cristalliser lentement.', 4),
    ('71d7e59f-13a4-55ac-9b93-6901a1629a83'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Quelle spectroscopie révèle surtout les groupes fonctionnels ?', 'mcq', '["La spectroscopie infrarouge","La RMN","La spectrophotométrie UV-visible","La chromatographie"]'::jsonb, 0, 'La RMN, elle, renseigne sur le squelette carboné.', 5),
    ('84fc045e-37bb-5993-9c39-ac6f3f75e1f0'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Le rendement d’une synthèse peut-il atteindre 100 % en pratique ?', 'mcq', '["Non, chaque étape en perd un peu","Oui, si la réaction est totale","Oui, avec un catalyseur","Oui, si le mélange est stœchiométrique"]'::jsonb, 0, 'Réaction incomplète et pertes de manipulation s’additionnent.', 6),
    ('f6e0590e-6bad-57c3-8874-c6a68920ce5b'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Sur une chromatographie, deux taches à la même hauteur signalent la même espèce chimique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le principe de l’identification par comparaison à une référence.', 7),
    ('25eca25b-23eb-5360-a6f9-131a51b15ca7'::uuid, 'fc7bedbe-0c84-554c-8001-dff3acce779e'::uuid, 'Pourquoi ajoute-t-on de la pierre ponce dans le ballon ?', 'mcq', '["Pour réguler l’ébullition","Pour catalyser la réaction","Pour colorer le mélange","Pour absorber les impuretés"]'::jsonb, 0, 'Elle évite les soubresauts d’une ébullition brutale.', 8),
    ('1206abd9-e983-526a-a4ef-650991f90c95'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Quels sont les produits d’une combustion complète d’un hydrocarbure ?', 'mcq', '["Du dioxyde de carbone et de l’eau","Du monoxyde de carbone et de la suie","Du dioxygène et du carbone","De l’eau seulement"]'::jsonb, 0, 'La combustion incomplète, elle, produit CO et des particules.', 1),
    ('c4430c33-eb06-5aae-816c-8b47825d4b38'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Une combustion est une réaction endothermique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est EXOTHERMIQUE : elle libère de l’énergie vers le milieu.', 2),
    ('d36218e3-87dd-5e68-a0d2-9525766705d4'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Quel gaz dangereux se forme lors d’une combustion incomplète ?', 'mcq', '["Le monoxyde de carbone","Le dioxyde de carbone","Le dioxygène","Le diazote"]'::jsonb, 0, 'Inodore et incolore, il se fixe sur l’hémoglobine à la place du dioxygène.', 3),
    ('012d4a1d-8710-59dd-9650-1e59ce174bb8'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Dans quel ordre ajuste-t-on l’équation d’une combustion ?', 'mcq', '["Carbone, hydrogène, puis oxygène","Oxygène, carbone, puis hydrogène","Hydrogène, oxygène, puis carbone","Dans n’importe quel ordre"]'::jsonb, 0, 'L’oxygène en dernier, parce qu’il apparaît dans les deux produits.', 4),
    ('62dd45f1-e7ce-5c49-801f-2775722e216f'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Qu’est-ce que le pouvoir calorifique d’un combustible ?', 'mcq', '["L’énergie libérée par la combustion complète d’un kilogramme de ce combustible","La température de sa flamme","La masse de CO₂ produite","Le volume de dioxygène nécessaire"]'::jsonb, 0, 'Il permet de calculer l’énergie dégagée par une masse donnée.', 5),
    ('22a81212-3e96-5f3d-8244-b6510785271e'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Une flamme jaune et fumeuse signale une combustion complète.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle signale une combustion INCOMPLÈTE, avec formation de suie.', 6),
    ('c543bc03-8f58-598d-9c85-b5267853ffb5'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Comment le bilan carbone de la biomasse diffère-t-il de celui des combustibles fossiles ?', 'mcq', '["Le carbone relâché a été prélevé récemment par photosynthèse","La biomasse ne produit pas de CO₂","La biomasse libère moins d’énergie","La biomasse ne produit aucun polluant"]'::jsonb, 0, 'Les fossiles, eux, libèrent un carbone stocké depuis des millions d’années.', 7),
    ('66cb0e61-aa67-53f5-8372-6ae3e30c9aec'::uuid, '87b3e35f-3682-5ef3-8de5-a612af77e5d7'::uuid, 'Comment calcule-t-on l’énergie d’une réaction à partir des énergies de liaison ?', 'mcq', '["En comparant l’énergie dépensée pour rompre les liaisons et celle libérée en en formant","En additionnant toutes les énergies de liaison","En multipliant par la masse molaire","En mesurant la température de la flamme"]'::jsonb, 0, 'Le bilan est négatif pour une réaction exothermique.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('physique-chimie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('physique-chimie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 270 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 270 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
